#!/usr/bin/env node
import { spawn } from 'node:child_process';
import { readdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = path.resolve(fileURLToPath(new URL('.', import.meta.url)), '..', '..');

async function discover(dir) {
  const found = [];
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return found;
  }
  for (const entry of entries) {
    if (entry.name === 'node_modules' || entry.name === '.git') continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      found.push(...(await discover(full)));
    } else if (entry.isFile() && entry.name.endsWith('.test.ts')) {
      found.push(full);
    }
  }
  return found;
}

async function main() {
  const arg = process.argv[2];
  let files;

  if (arg) {
    const target = path.resolve(repoRoot, arg);
    files = target.endsWith('.test.ts') ? [target] : await discover(target);
  } else {
    files = await discover(path.join(repoRoot, '_local'));
  }

  if (files.length === 0) {
    console.error('No *.test.ts files found.');
    process.exit(1);
  }

  const child = spawn(
    process.execPath,
    ['--test', '--test-reporter=spec', '--no-warnings=MODULE_TYPELESS_PACKAGE_JSON', ...files],
    { cwd: repoRoot, stdio: 'inherit' }
  );

  child.on('exit', (code) => process.exit(code ?? 1));
}

main();

